using System;
using MET.Core;
class UI8Program {
 static int checks;
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static void Near(double a,double b,string label)=>Check(Math.Abs(a-b)<1e-8,label+": "+a+" vs "+b);
 static Game New(Catalog c){var g=new Game(c);g.new_game(800,1000);Check(g.select_block(0)=="","select");Check(g.choose_origin(g.s["origin_choices"][0].Text)=="","origin");g.s["currency"]=10000;Civic.ensure(g);g.s["civic032"]["cash_anchor"]=10000;return g;}
 static string Job(Game g){var id=g.create_building("workshop","1,0","steel")["id"].Text;var p=g.s["projects"][id];p["job"]=V.Map("work",100.0,"total",100.0,"material",100.0,"cp",true);g.s["projects"]["municipal"]["inventory"]["material"]=1000;g.refresh_metrics();return id;}
 static void Main(string[] args) {
  var c=new Catalog(args[0]);var g=New(c);var old=g.s.ToJson(false,true);Check(Construction.crews(g).Count==0,"old saves have no crews");Construction.crew_quote(g);Construction.capacity_breakdown(g);Check(old==g.s.ToJson(false,true),"crew read APIs do not mutate");
  Near(Construction.crew_quote(g)["cost"].Double,60,"first quote");Check(Construction.hire_crew(g)=="","first purchase");Near(g.s["currency"].Double,9940,"upfront payment");Near(Construction.crew_quote(g)["cost"].Double,120,"second quote");Check(Construction.hire_crew(g)=="","second purchase");Near(Construction.crew_quote(g)["cost"].Double,240,"third quote");Near(g.s["civic032"]["transactions"][0]["cash"].Double,-60,"civic purchase receipt");Near(g.s["civic032"]["transactions"][1]["cash"].Double,-120,"second civic receipt");
  g.s["currency"]=239;old=g.s.ToJson(false,true);Check(Construction.hire_crew(g)!="","unaffordable purchase rejected");Check(old==g.s.ToJson(false,true),"failed purchase has no changes");
  var remaining=Construction.crews(g)[0]["remaining_months"].Double;g.s["settings"]["user_paused"]=true;Clock.advance(g,500);Near(Construction.crews(g)[0]["remaining_months"].Double,remaining,"pause preserves duration");Clock.resume(g,50000);Near(Construction.crews(g)[0]["remaining_months"].Double,remaining,"offline preserves duration");
  g=New(c);string id=Job(g);Check(Construction.hire_crew(g)=="","settlement crew");g.s["block"]["construction_capacity"]=2;g.compiled["options"]["construction_efficiency"]=2;g.s["metrics"]["energy_ratio"]=1;Near(Construction.capacity(g),8,"crew nominal is not multiplied by bonus");g.s["local_hours"]=.5;Construction.tick(g,.5);Near(g.s["projects"][id]["job"]["work"].Double,96,"first half-month");g.s["local_hours"]=1.25;Construction.tick(g,.75);Near(g.s["projects"][id]["job"]["work"].Double,91,"expiry inside interval includes only active portion");Near(g.s["block"]["construction_last"]["crew_cp"].Double,2,"partial expiry crew CP");Check(Construction.crews(g).Count==0,"expiry removes active count");Near(Construction.crew_quote(g)["cost"].Double,60,"expired crew does not increase quote");
  g=New(c);id=Job(g);Construction.hire_crew(g);g.s["block"]["construction_capacity"]=4;g.s["block"]["city_cp_reserve"]=.5;g.s["block"]["city_context"]=true;g.s["metrics"]["energy_ratio"]=.5;g.s["local_hours"]=.5;Construction.tick(g,.5);Near(g.s["block"]["city_cp_last"]["cp"].Double,.5,"city reserve excludes purchased CP");Near(g.s["block"]["construction_last"]["cp"].Double,1.5,"energy applies to purchased CP");
  g=New(c);Construction.hire_crew(g);g.s["local_hours"]=1.1;Construction.tick(g,1.1);Check(Construction.crews(g).Count==0,"empty queue still expires");
  g=New(c);id=Job(g);Construction.hire_crew(g);Check(Sim.tick(g,1.25)=="","real simulation crossing expiry");Near(g.s["block"]["construction_last"]["crew_cp"].Double,4*g.s["metrics"]["energy_ratio"].Double,"Sim uses pre-expiry portion despite advanced local time");
  old=g.s.ToJson(false,true);var summary=TileSummary.describe(g,"1,0");Check(old==g.s.ToJson(false,true),"tile summary read-only");Check(summary["settlement_available"].Bool,"actual settlement available");double construction=0;foreach(var row in summary["resources"])if(row["resource"].Text=="material")construction=row["construction_material"].Double;Near(construction,g.s["block"]["construction_last"]["material"].Double/1.25,"construction material receipt matches settlement");
  double fiscal=0;foreach(var row in g.s["metrics"]["fiscal_sources"])if(row["aggregate"].Text=="tax")fiscal+=row["rate"].Double;double aggregate=0;foreach(var row in g.s["metrics"]["fiscal_ledger"])if(row["kind"].Text=="income"&&row["source_id"].Text=="municipal"&&row["name"].Text=="人头税")aggregate+=row["rate"].Double;Near(fiscal,aggregate,"tax source receipts reconcile with untouched aggregate");
  g=New(c);id=Job(g);Construction.hire_crew(g);var loaded=new Game(c);loaded.s=V.Parse(g.s.ToJson());loaded.refresh_metrics();Near(Construction.crew_quote(loaded)["cost"].Double,120,"crew survives serialized state reload");Near(Construction.crews(loaded)[0]["remaining_months"].Double,1,"loaded duration retained");
  loaded.s["projects"]["municipal"]["inventory"]["material"]=0;loaded.s["local_hours"]=.5;Construction.tick(loaded,.5);Near(loaded.s["block"]["construction_last"]["cp"].Double,0,"no materials means no construction despite crews");Near(Construction.crews(loaded)[0]["remaining_months"].Double,.5,"waiting for material still consumes game duration");
  Console.WriteLine("UI8 CORE PASS "+checks+" assertions; no Player/UI acceptance performed.");
 }
}
